"""mpl_toolkits.axes_grid1.mpl_axes — wrapper axes."""

from matplotlib.axes._axes import Axes

class Axes(Axes):
    class AxisDict(dict):
        def __init__(self, axes):
            super().__init__()
            self._axes = axes


# ─── Added: SimpleAxisArtist + SimpleChainedObjects ─────────────────


class SimpleChainedObjects:
    """A list of artists that forwards attribute access to every member.
    Used by axes_grid1 to expose a group of spines/ticks as a single
    object on which the user can call setters.
    """

    def __init__(self, objects):
        self._objects = list(objects)

    def __iter__(self):
        return iter(self._objects)

    def __getitem__(self, idx):
        return self._objects[idx]

    def __getattr__(self, name):
        if name.startswith('_'):
            raise AttributeError(name)
        def _fanout(*args, **kwargs):
            results = []
            for obj in self._objects:
                fn = getattr(obj, name, None)
                if callable(fn):
                    try: results.append(fn(*args, **kwargs))
                    except Exception: results.append(None)
            return results
        return _fanout


class SimpleAxisArtist:
    """Tiny axis-artist surrogate used by :class:`Axes` in axes_grid1.
    Holds the axis it belongs to plus a flag for whether it's visible.
    """

    def __init__(self, axis, axisnum, major_label_visible=True):
        self._axis = axis
        self._axisnum = axisnum
        self._visible = True
        self._major_label_visible = major_label_visible

    def toggle(self, all=None, ticks=None, ticklabels=None, label=None):
        if all is not None:    self._visible = bool(all)
        if ticks is not None:  self._visible = bool(ticks)

    def set_visible(self, b):  self._visible = bool(b)
    def get_visible(self):     return self._visible
